import java.util.*;
class BST {

	private Node root;

	public BST() {
		this.root = null;
	}

	public boolean isEmpty() {
		return this.root == null;
	}

	public void add(int value) {

		if (isEmpty())
			this.root = new Node(value);
		else
			this.root.add(value);
	}

    public int altura() {

        if (this.isEmpty()) return -1;
        return altura(this.root);

    }

    public int count(Node node) {

        if (node == null) return 0;
        else return 1 + count(node.left) + count(node.right);
    }

    private int altura(Node node) {

        if (node == null)
            return -1;
        else
            return 1 + Integer.max(altura(node.left), altura(node.right));

    }

	public ArrayList search(int value, ArrayList l) {
		if (isEmpty()) return l;
		else return this.root.search(value, l);
	}

    public int menorDistancia(int v) {

        int md = Integer.MAX_VALUE;
        Node aux = root;
        int out = -1;

        while (aux != null) {

            if (Math.abs(v - aux.value) < md) {
                md = Math.abs(v - aux.value);
                out = aux.value;
            }


            if (aux.value > v)
                aux = aux.left;
            else if (aux.value == v) return v;
            else aux = aux.right;

        }

        return out;

    }

	public void preOrder(ArrayList l) {

		if (root != null) {
			this.root.preOrder(l);
		}

	}

	public void inOrder(ArrayList l) {

		if (root != null) {
			this.root.inOrder(l);
		}

	}

    public void posOrder(ArrayList l) {

		if (root != null) {
			this.root.posOrder(l);
		}

	}


	public int min() {

		if (isEmpty()) throw new RuntimeException("empty tree");

		Node aux = root;
		while (aux.left != null)
			aux = aux.left;

		return aux.value;

	}

	public int max() {
		if(isEmpty()) throw new RuntimeException();
		return this.max(root);
	}

	private int max(Node node) {
		if (node.right == null)
			return node.value;
		return this.max(node.right);
	}

	public int sum() {
		return sum(this.root);
	}

	private int sum(Node node) {
		if (node == null) return 0;
		return node.value + sum(node.left) + sum(node.right);
	}

	public int countLeaves() {
		return this.countLeaves(root);
	}

	private int countLeaves(Node node) {

		if (node != null) {
			if (node.left == null && node.right == null)
				return 1;
			else {
				return countLeaves(node.left) + countLeaves(node.right);
			}
		}
		return 0;

	}

    public int contaMaiores(int v) {
        if (isEmpty()) return 0;
        else return contaMaiores(v, root);
    }

    public int contaMaiores(int v, Node node) {
        if (node == null) return 0;

        if (node.value > v) {

            return 1 + count(node.right) +  contaMaiores(v, node.left);

        } else {

            return contaMaiores(v, node.right);

        } 


    }

    public int contaMenores(int v) {
        if (isEmpty()) return 0;
        else return contaMenores(v, root);
    }

    public int contaMenores(int v, Node node) {
        if (node == null) return 0;

        if (node.value <= v) {

            return 1 + count(node.left) +  contaMenores(v, node.right);

        } else {

            return contaMenores(v, node.left);

        } 


    }



    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);
        String input = scan.nextLine();

        String[] strArray = input.split(" ");
        int[] intArray = new int[strArray.length];
        for(int i = 0; i < strArray.length; i++) {
            intArray[i] = Integer.parseInt(strArray[i]);
        }

        BST tree = new BST();
        for (int i : intArray) {
            tree.add(i);
        }

        Integer v = Integer.parseInt(scan.nextLine());

        ArrayList l = new ArrayList();
        tree.preOrder(l);
        System.out.println(Arrays.toString(l.toArray()));
        System.out.println(tree.contaMenores(v, tree.root));


    }


}

