	private Node root;

	public BST() {
		this.root = null;
	}

	public boolean isEmpty() {
		return this.root == null;
	}

	public void add(int value) {

		if (isEmpty())
			this.root = new Node(value);
		else
			this.root.add(value);
	}

	public Node search(int value) {
		if (isEmpty()) return null;
		else return this.root.search(value);
	}

	public void preOrder(ArrayList l) {

		if (root != null) {
			this.root.preOrder(l);
		} 

	}

	public void inOrder(ArrayList l) {

		if (root != null) {
			this.root.inOrder(l);
		} 

	}

    public void posOrder(ArrayList l) {

		if (root != null) {
			this.root.posOrder(l);
		} 

	}


	public int min() {

		if (isEmpty()) throw new RuntimeException("empty tree");

		Node aux = root;
		while (aux.left != null)
			aux = aux.left;

		return aux.value;

	}

	public int max() {
		if(isEmpty()) throw new RuntimeException();
		return this.max(root);
	}

	private int max(Node node) {
		if (node.right == null)
			return node.value;
		return this.max(node.right);
	}

