	}

	public void add(int value) {

		if (isEmpty())
			this.root = new Node(value);
		else
			this.root.add(value);
	}

    public int altura() {

        if (this.isEmpty()) return -1;
        return altura(this.root);

    }

    public int count(Node node) {

        if (node == null) return 0;
        else return 1 + count(node.left) + count(node.right);

    }

    private int altura(Node node) {

        if (node == null)
            return -1;
        else
            return 1 + Integer.max(altura(node.left), altura(node.right));

    }

	public ArrayList search(int value, ArrayList l) {
		if (isEmpty()) return l;
		else return this.root.search(value, l);
	}

    public int menorDistancia(int v) {

        int md = Integer.MAX_VALUE;
        Node aux = root;
        int out = -1;

        while (aux != null) {

            if (Math.abs(v - aux.value) < md) {
                md = Math.abs(v - aux.value);
                out = aux.value;
            }


            if (aux.value > v)
                aux = aux.left;
            else if (aux.value == v) return v;
            else aux = aux.right;

        }

        return out;

    }

