		}
		if (indice < livros.length)
			sortComPrints(livros, indice + 1);
	}

	private static void swap(String[] arr, int i1, int i2) {
		String temp = arr[i1];
		arr[i1] = arr[i2];
		arr[i2] = temp;
	}
}

